// The incoming msg.payload is now the array of water reminders from the change node
const waterReminders = msg.payload;

// Ensure it's actually an array and not empty
if (!Array.isArray(waterReminders) || waterReminders.length === 0) {
    node.warn("No water reminders array found in msg.payload or it's empty.");
    return null; // Stop the flow if no valid array
}

// Generate a random index
const randomIndex = Math.floor(Math.random() * waterReminders.length);

// Set msg.payload to the randomly selected reminder
msg.reminder = waterReminders[randomIndex];

return msg;

// At this point, msg.payload is ALREADY a parsed array/object thanks to the JSON node
const recipients = msg.payload;

// Ensure we have a valid array
if (!Array.isArray(recipients)) {
    node.error("Expected an array of recipients, but received something else.", msg);
    return null;
}

// Retrieve the saved reminder text
const reminderText = msg.reminder || "FALL IN! Time to hydrate, Recruit! 🚰";

// Filter for active users only (enabled: true or undefined)
const activeRecipients = recipients.filter(user => user.enabled !== false);

// If no active recruits, stop processing
if (activeRecipients.length === 0) {
    return null;
}

// Map each active recipient into an individual Telegram message object
const messages = activeRecipients.map(user => ({
    payload: {
        chatId: user.chatId,
        type: "message",
        content: `Attention Recruit ${user.name}!\n\n${reminderText}`,
        parse_mode: "Markdown"
    }
}));

// Return array of messages so Node-RED emits them individually to Telegram Sender
return [messages];

// Preserve telegram details and set action flag
msg.action = "start";
msg.userChatId = msg.payload.chatId;
msg.firstName = msg.originalMessage?.from?.first_name || "Recruit";

return msg;

// Preserve telegram details and set action flag
msg.action = "stop";
msg.userChatId = msg.payload.chatId;
msg.firstName = msg.originalMessage?.from?.first_name || "Recruit";

return msg;

// Read current recipients array from file
let recipients = Array.isArray(msg.payload) ? msg.payload : [];

const chatId = msg.userChatId;
const firstName = msg.firstName;
const action = msg.action;

let existingUser = recipients.find(u => String(u.chatId) === String(chatId));
let replyText = "";

if (action === "start") {
    if (existingUser) {
        if (existingUser.enabled === false) {
            existingUser.enabled = true;
            replyText = `FALL IN! Welcome back, Recruit ${firstName}! Re-subscribed to Nag Master 3000! 💧`;
        } else {
            replyText = `Recruit ${firstName}, you already fell in long ago! Keep drinking water, don't blur! 🚰`;
        }
    } else {
        recipients.push({
            name: firstName,
            chatId: chatId,
            enabled: true
        });
        replyText = `FALL IN! Welcome to the platoon, Recruit ${firstName}! Hydration reminders locked and loaded! 🚰`;
    }
} else if (action === "stop") {
    if (existingUser && existingUser.enabled !== false) {
        existingUser.enabled = false;
        replyText = `FALL OUT! Goodbye Recruit ${firstName}. You are dismissed from reminders. Send /fall-in anytime to report back! 👋`;
    } else {
        replyText = `Recruit ${firstName}, you aren't even in the platoon! Send /fall-in if you want to join!`;
    }
}

// Output 1: Stringify array so File Out saves valid JSON format
const fileMsg = { payload: JSON.stringify(recipients, null, 2) };

// Output 2: Confirmation reply back to Telegram user
const replyMsg = {
    payload: {
        chatId: chatId,
        type: "message",
        content: replyText
    }
};

return [fileMsg, replyMsg];

const response = msg.payload;

try {
    // Access readings under payload.data.items[0].readings
    const items = response?.data?.items || [];
    const readings = items[0]?.readings || {};
    const pm25OneHr = readings.pm25_one_hourly || {};

    const regions = ['north', 'south', 'east', 'west', 'central'];

    // Determine action advisory based on 1-hour PM2.5 levels
    function getAction(pm25) {
        if (pm25 >= 251) {
            return "MINIMISE all outdoor activity";
        } else if (pm25 >= 151) {
            return "AVOID strenuous outdoor activity";
        } else if (pm25 >= 56) {
            return "REDUCE strenuous outdoor activity";
        }
        return "CONTINUE with normal activities";
    }

    let regionReports = [];

    regions.forEach(region => {
        const pm25 = pm25OneHr[region] ?? 'N/A';
        const action = typeof pm25 === 'number' ? getAction(pm25) : 'N/A';

        // Capitalize region name
        const regionName = region.charAt(0).toUpperCase() + region.slice(1);

        regionReports.push(
            `*${regionName}:* 1-hr PM2.5 - ${pm25} µg/m³\n` +
            ` • *Action:* ${action}`
        );
    });

    const message = `🌬️ *Singapore Hourly Air Quality Advisory*\n\n` + 
                    regionReports.join('\n\n');

    msg.reminder = message;
    return msg;
} catch (e) {
    node.error("Failed to parse Air Quality API data: " + e.message, msg);
    return null;
}

const recipients = msg.payload;

if (!Array.isArray(recipients)) {
    node.error("Expected an array of recipients in /data/recipients.json", msg);
    return null;
}

const airReport = msg.reminder;
const activeRecipients = recipients.filter(user => user.enabled !== false);

if (activeRecipients.length === 0) {
    return null;
}

const messages = activeRecipients.map(user => ({
    payload: {
        chatId: user.chatId,
        type: "message",
        content: `Attention Recruit ${user.name}!\n\n${airReport}`,
        parse_mode: "Markdown"
    }
}));

return [messages];
